    private void beginGrid(Minecraft client){var clicks=new ArrayList<int[]>();var types=new java.util.LinkedHashSet<Item>();for(int i=0;i<9;i++)if(ingredient(i)!=Items.AIR)types.add(ingredient(i));for(Item item:types){var cells=new ArrayList<Integer>();for(int i=0;i<9;i++)if(ingredient(i)==item)cells.add(i);int used=0;for(int slot=0;slot<36 && used<cells.size();slot++){ItemStack actual=client.player.getInventory().getItem(slot);if(!actual.is(item))continue;int from=playerSlot(client,slot),n=Math.min(actual.getCount(),cells.size()-used);clicks.add(new int[]{from,0});for(int i=0;i<n;i++)clicks.add(new int[]{cells.get(used++)+2,1});clicks.add(new int[]{from,0});}require(used==cells.size(),"actual physical finite ingredients cover recipe "+item);}gridClicks=List.copyOf(clicks);gridIndex=0;onServer(client,()->{var p=serverPlayer(client);var projection=new SimpleContainer(11);var needed=new LinkedHashMap<Item,Integer>();for(int i=0;i<9;i++){Item wanted=ingredient(i);if(wanted!=Items.AIR){needed.merge(wanted,1,Integer::sum);projection.setItem(i,stack(p,value->value.is(wanted)).copyWithCount(1));}}for(var entry:needed.entrySet())require(count(p,entry.getKey())>=entry.getValue(),"read-only recipe projection cannot hide shortage");projection.setItem(TileArcaneWorkbench.WAND_SLOT,paidGold.copy());requireRecipe(ArcaneCrafting.find(p,projection));});next(Step.GRID);}
