    private void patch(ServerPlayer player){
        ServerLevel level=player.serverLevel();
        for(int x=patchMin().getX()>>4;x<=patchMax().getX()>>4;x++)for(int z=patchMin().getZ()>>4;z<=patchMax().getZ()>>4;z++)level.getChunk(x,z);
        for(AABB area:ownedAreas())require(level.getEntitiesOfClass(ItemEntity.class,area).isEmpty() && level.getEntitiesOfClass(ExperienceOrb.class,area).isEmpty(),"all owned areas refuse inherited loose items/XP, never clear them");
        for(AABB area:List.of(patchBounds(),oldMachineBounds()))require(level.getEntitiesOfClass(LivingEntity.class,area,entity->entity!=player).isEmpty(),"bench clearing/mining areas refuse ALL other living entities, never clear them");
        // The accepted scene already contains a named old cow and wild mobs.
        // None are inputs, targets or objects to erase. The scene is NOT cleared:
        // fixtures() refuses overlap at EVERY exact block write/device cell.
        report.put("inherited_scene_living_entities_LEFT_UNTOUCHED",level.getEntitiesOfClass(LivingEntity.class,sceneBounds(),entity->entity!=player).stream().map(entity->Map.of("UUID",entity.getUUID().toString(),"type",BuiltInRegistries.ENTITY_TYPE.getKey(entity.getType()).toString(),"actual_native_position",entity.position().toString(),"entity_mutations_or_target_actions",0)).toList());
        require(pendingView(level).isEmpty(),"no inherited pending owners");
        for(BlockPos pos:BlockPos.betweenClosed(patchMin(),patchMax()))require(!oldBlocks.containsKey(pos) && level.getBlockEntity(pos)==null && !BuiltInRegistries.BLOCK.getKey(level.getBlockState(pos).getBlock()).getNamespace().equals("thaumcraft"),"NEW bench patch never overwrites old/TC/BE cell "+pos);
        for(BlockPos pos:BlockPos.betweenClosed(patchMin(),patchMax()))level.setBlockAndUpdate(pos,pos.getY()<bench.getY()?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState());
        level.setBlockAndUpdate(bench,ThaumcraftArcane.ARCANE_WORKBENCH.get().defaultBlockState());report.put("declared_NEW_bench_patch",Map.of("min",patchMin().toShortString(),"max",patchMax().toShortString(),"floor_top",216,"old_area_clearing",false));
    }
