    /** Pure accepted queue layout; save() can ACK in-flight admission and is NOT
     * an observation API. Exclude matching live UUID/stack from extra escrow. */
    @SuppressWarnings("unchecked") private List<PendingView> pendingView(ServerLevel level){try{require(level.getServer().isSameThread(),"pending view on SAME server thread");var field=DeferredItemDrops.class.getDeclaredField("FACTORY");field.setAccessible(true);var factory=(SavedData.Factory<DeferredItemDrops>)field.get(null);var queue=level.getDataStorage().get(factory,"thaumcraft_pending_inventory_drops");if(queue==null)return List.of();require(queue.quarantinedCount()==0,"no unaccounted quarantined outputs");var rows=new ArrayList<Object>();for(Object row:(Iterable<?>)BookClientSmoke.field(queue,"pending"))rows.add(row);Object flight=BookClientSmoke.field(queue,"inFlight");if(flight!=null && !(boolean)BookClientSmoke.field(flight,"accepted"))rows.add(BookClientSmoke.field(flight,"entry"));Set<UUID> settled=(Set<UUID>)BookClientSmoke.field(queue,"settled");var receiptField=DeferredItemDrops.class.getDeclaredField("LIVE_RECEIPTS");receiptField.setAccessible(true);Set<UUID> receipts=((Map<ServerLevel,Set<UUID>>)receiptField.get(null)).getOrDefault(level,Set.of());var ids=new HashSet<UUID>();var result=new ArrayList<PendingView>();for(Object row:rows){UUID id=(UUID)BookClientSmoke.field(row,"id");BlockPos source=(BlockPos)BookClientSmoke.field(row,"source");if(!ownedPosition(Vec3.atCenterOf(source)) || settled.contains(id) || receipts.contains(id))continue;require(ids.add(id),"one actual escrow/in-flight owner per UUID");ItemStack actual=(ItemStack)BookClientSmoke.field(row,"stack");if(level.getEntity(id) instanceof ItemEntity item && !item.isRemoved() && ItemStack.matches(item.getItem(),actual))continue;boolean routing=(boolean)BookClientSmoke.field(row,"routing");String phase=routing?"ROUTING":flight!=null && BookClientSmoke.field(flight,"entry")==row?"IN_FLIGHT":"DROP_READY";result.add(new PendingView(id,source.immutable(),actual.copy(),phase,(Vec3)BookClientSmoke.field(row,"position"),(Vec3)BookClientSmoke.field(row,"motion")));}return List.copyOf(result);}catch(ReflectiveOperationException error){throw new IllegalStateException("Accepted queue pure-view layout needs reconciliation, NEVER substitute save/flush",error);}}
    private void approachDrop(ServerPlayer player,UUID id,ItemStack dropped,String name){require(id!=null && dropped!=null && player.serverLevel().getEntity(id) instanceof ItemEntity item && ItemStack.matches(item.getItem(),dropped),"SAME untouched native UUID until actual contact pickup "+name);ItemEntity item=(ItemEntity)player.serverLevel().getEntity(id);double[] offsets={0,.8,-.8,1.05,-1.05,1.2,-1.2};for(int rise=0;rise<=4;rise++)for(double x:offsets)for(double z:offsets){Vec3 at=new Vec3(item.getX()+x,216+rise,item.getZ()+z);AABB body=player.getBoundingBox().move(at.subtract(player.position()));BlockPos floor=BlockPos.containing(at.x,at.y-.01,at.z);if(!ownedPosition(at) || !player.level().noCollision(player,body) || player.level().getBlockState(floor).getCollisionShape(player.level(),floor).isEmpty() || !body.inflate(1,.5,1).intersects(item.getBoundingBox()))continue;physicalRows.add(Map.of("native_tick",player.level().getGameTime(),"event","collision-checked SAME UUID actor contact approach","name",name,"UUID",id.toString(),"unmoved_item_position",item.position().toString(),"supported_player_position",at.toString(),"actual_existing_support",floor.toShortString(),"native_contact_envelope",true,"item_relocations_or_refunds",0));stand(player,at.x,at.y,at.z);return;}throw new IllegalStateException("No supported native contact approach for SAME "+name+" UUID at "+item.position());}

    private void capture(int index){require(captures==index,"exact contiguous capture154-163 order");++captures;report.put("actual_captures_requested",captures);capture.accept(CAPTURES.get(index));}
    private boolean hand(Minecraft client,Predicate<ItemStack> wanted)throws ReflectiveOperationException{require(client.player.containerMenu==client.player.inventoryMenu,"native hand SWAP outside menus only");if(!wanted.test(client.player.getInventory().getItem(HAND_SLOT))){click(client,playerSlot(client,itemSlot(client.player,wanted)),HAND_SLOT,ClickType.SWAP);handChangedAt=client.player.tickCount;return false;}if(client.player.tickCount-handChangedAt<6)return false;select(client,HAND_SLOT);return true;}
    private boolean emptyHand(Minecraft client)throws ReflectiveOperationException{return hand(client,ItemStack::isEmpty);}
    private static void select(Minecraft client,int slot)throws ReflectiveOperationException{client.player.getInventory().selected=slot;var method=client.gameMode.getClass().getDeclaredMethod("ensureHasSentCarriedItem");method.setAccessible(true);method.invoke(client.gameMode);}
    private static int playerSlot(Minecraft client,int index){return client.player.containerMenu.slots.stream().filter(slot->slot.container==client.player.getInventory() && slot.getContainerSlot()==index).findFirst().orElseThrow().index;}
    private static void click(Minecraft client,int slot,int button,ClickType type){client.gameMode.handleInventoryMouseClick(client.player.containerMenu.containerId,slot,button,type,client.player);}
    private static void sendRotation(Minecraft client,Vec3 point){lookAt(client,point);client.player.connection.send(new ServerboundMovePlayerPacket.Rot(client.player.getYRot(),client.player.getXRot(),client.player.onGround()));}
    private boolean aimReady(Minecraft client,BlockPos pos,Direction face,Vec3 point){require(client.player.canInteractWithBlock(pos,0),"actual native Survival reach "+pos);sendRotation(client,point);if(!pos.equals(useAimPos) || face!=useAimFace || !point.equals(useAimPoint)){useAimPos=pos.immutable();useAimFace=face;useAimPoint=point;useAimStarted=client.player.tickCount;return false;}return client.player.tickCount-useAimStarted>=6;}
    private boolean use(Minecraft client,BlockPos pos,Direction face,Vec3 point){if(!aimReady(client,pos,face,point))return false;require(client.gameMode.useItemOn(client.player,InteractionHand.MAIN_HAND,new BlockHitResult(point,face,pos,false)).consumesAction(),"actual native C2S useItemOn "+pos+"/"+face);clearAim();return true;}
    private void clearAim(){useAimPos=null;useAimFace=null;useAimPoint=null;}
    private static void lookAt(Minecraft client,Vec3 point){Vec3 delta=point.subtract(client.player.getEyePosition());client.player.setYRot((float)Math.toDegrees(Math.atan2(-delta.x,delta.z)));client.player.yRotO=client.player.getYRot();client.player.setXRot((float)-Math.toDegrees(Math.atan2(delta.y,Math.hypot(delta.x,delta.z))));client.player.xRotO=client.player.getXRot();}
    private static void stand(ServerPlayer player,double x,double y,double z){var body=new AABB(x-.3,y+.001,z-.3,x+.3,y+1.8,z+.3);BlockPos floor=BlockPos.containing(x,y-.01,z);require(player.level().noCollision(player,body) && !player.level().getBlockState(floor).getCollisionShape(player.level(),floor).isEmpty(),"collision-checked actor on actual existing/declared support");player.teleportTo(x,y,z);}
    private void chargeCamera(ServerPlayer player){stand(player,1623.5,216,376.6);}
    private void upperCamera(ServerPlayer player){stand(player,1551.5,219,380.5);}
    private void relayCamera(ServerPlayer player){stand(player,1558.5,218,380.5);}
    private void wideCamera(ServerPlayer player){stand(player,1555.5,216,383.5);}
    private static Vec3 widePoint(){return new Vec3(1554.7,218.5,377.5);}
    private void consumerLowCamera(ServerPlayer player){stand(player,1567.4,216,377.5);}
    private void consumerHighCamera(ServerPlayer player){stand(player,1567.5,219,375.5);}
    private Vec3 valveUpPoint(){return Vec3.atCenterOf(valvePos).add(0,.35,0);}
    private Vec3 upperLeverPoint(){return Vec3.atCenterOf(upperLever).add(0,0,-.3125);}
    private static void releaseKeys(Minecraft client){client.options.keyUse.setDown(false);client.options.keyAttack.setDown(false);client.options.keyShift.setDown(false);}
    private void releaseInputs(Minecraft client){releaseUse(client);aimCharge=false;ClientTickEvent.CLIENT_PRE.unregister(nativeClientPre);releaseKeys(client);if(client.player!=null && client.gameMode!=null)client.gameMode.stopDestroyBlock();if(previousCamera!=null)client.options.setCameraType(previousCamera);}
    private static ItemEntity clientDrop(Minecraft client,UUID id){for(var entity:client.level.entitiesForRendering())if(entity instanceof ItemEntity item && item.getUUID().equals(id) && !item.isRemoved())return item;return null;}
    private static BlockPos serverSessionNode(ServerPlayer player,ItemStack wand){try{var field=ItemWandCasting.class.getDeclaredField("SERVER_NODE_USES");field.setAccessible(true);Object session=((Map<?,?>)field.get(null)).get(player);require(session!=null && BookClientSmoke.field(session,"hand")==InteractionHand.MAIN_HAND && BookClientSmoke.field(session,"stack")==wand,"actual SERVER selected node session exact hand/stack");return ((BlockPos)BookClientSmoke.field(session,"pos")).immutable();}catch(ReflectiveOperationException error){throw new IllegalStateException("Pure native wand session view needs reconciliation",error);}}
    private static boolean sameExceptVis(ItemStack first,ItemStack second){WandData a=ItemWandCasting.data(first),b=ItemWandCasting.data(second);if(!a.rod().equals(b.rod()) || !a.cap().equals(b.cap()))return false;ItemStack x=first.copy(),y=second.copy();x.remove(ThaumcraftContent.WAND_DATA.get());y.remove(ThaumcraftContent.WAND_DATA.get());return ItemStack.matches(x,y);}
    private static void verifyDebit(ItemStack before,ItemStack after,Map<String,Integer> price){require(sameExceptVis(before,after),"all payer non-vis components exact");for(String type:WandData.PRIMALS)require(ItemWandCasting.data(before).amount(type)-ItemWandCasting.data(after).amount(type)==price.getOrDefault(type,0),"EXACT native recipe centivis price "+type);}
    private static boolean affords(ItemStack wand,Map<String,Integer> price){return price.entrySet().stream().allMatch(entry->ItemWandCasting.data(wand).amount(entry.getKey())>=entry.getValue());}
    private static CompoundTag beTag(BlockEntity tile){return tile.saveWithFullMetadata(tile.getLevel().registryAccess()).copy();}
    private static String tag(Aspect value){return value==null?"":value.getTag();}
    private static Map<String,Integer> aspects(AspectList list){var out=new LinkedHashMap<String,Integer>();for(Aspect type:list.getAspects()){int n=list.getAmount(type);require(n>=0,"no negative live source/storage quantities");if(n>0)out.put(type.getTag(),n);}return Map.copyOf(out);}
    private static Map<String,Integer> singleton(Aspect type,int n){require(n>=0 && (n==0 || type!=null),"actual typed nonnegative source storage");return n==0?Map.of():Map.of(type.getTag(),n);}
    private static Map<String,Integer> typedStock(List<ItemStack> stacks){var out=new LinkedHashMap<String,Integer>();for(ItemStack value:stacks)if(value.is(crystalItem())){var data=ItemCrystalEssence.data(value);require(data!=null && data.amounts().size()==1 && data.amounts().values().iterator().next()==1 && BUDGET.containsKey(data.firstTag()),"native typed1 PER ITEM, not untyped/shard/ethereal/oldphial output");out.merge(data.firstTag(),value.getCount(),Integer::sum);}return Map.copyOf(out);}
    private static int sum(Map<String,Integer> values){return values.values().stream().mapToInt(Integer::intValue).sum();}
    private static int amount(Frame frame,String location,String type){return frame.locations().getOrDefault(location,Map.of()).getOrDefault(type,0);}
    private static int stored(Frame frame,String type){return frame.locations().values().stream().mapToInt(value->value.getOrDefault(type,0)).sum();}
    private static boolean phial(ItemStack value,String type){return value.is(ThaumcraftContent.FILLED_PHIAL.get()) && ItemEssence.data(value)!=null && ItemEssence.data(value).tag().equals(type);}
    private static boolean gold(ItemStack value){return value.is(ThaumcraftContent.WAND.get()) && ItemWandCasting.data(value).rod().equals("greatwood") && ItemWandCasting.data(value).cap().equals("gold");}
    private static boolean primary(ItemStack value){return value.is(ThaumcraftContent.WAND.get()) && ItemWandCasting.data(value).rod().equals("silverwood") && ItemWandCasting.data(value).cap().equals("thaumium");}
    private static int itemSlot(Player player,Predicate<ItemStack> wanted){for(int i=0;i<36;i++)if(wanted.test(player.getInventory().getItem(i)))return i;throw new IllegalStateException("Missing actual finite VisNet input/saved stack");}
    private static ItemStack stack(Player player,Predicate<ItemStack> wanted){return player.getInventory().getItem(itemSlot(player,wanted));}
    private static int count(Player player,Item item){return player.getInventory().items.stream().mapToInt(value->countStack(value,item)).sum();}
    private static int countStack(ItemStack value,Item item){return value.is(item)?value.getCount():0;}
    private static int emptyMain(Player player){for(int i=9;i<36;i++)if(player.getInventory().getItem(i).isEmpty())return i;throw new IllegalStateException("No genuinely empty main slot");}
